import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import add


class AddTests(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add.add(2, 2), 4)


if __name__ == "__main__":
    unittest.main()
